use std::sync::atomic::{AtomicI32, Ordering};

fn update_max(val: &AtomicI32, extra: i32) {
    let mut current = 0;
    loop {
        let new_val = current.max(extra);
        match val.⟦slot1⟧(
            current, new_val,
            Ordering::Relaxed, Ordering::Relaxed,
        ) {
            Ok(_) => break,
            Err(actual) => ⟦slot2⟧,
        }
    }
}

tests:
#[test]
fn test_update_max() {
    let a = AtomicI32::new(50);
    update_max(&a, 100);
    assert_eq!(a.load(Ordering::Relaxed), 100);
    update_max(&a, 20);
    assert_eq!(a.load(Ordering::Relaxed), 100);
}
